CREATE TYPE "InvitationStatus" AS ENUM ('PENDING','ACCEPTED','REVOKED','EXPIRED');
CREATE TYPE "ProjectStatus" AS ENUM ('PLANNING','ACTIVE','ON_HOLD','COMPLETED','ARCHIVED');
CREATE TYPE "ProjectPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TYPE "TaskStatus" AS ENUM ('TODO','IN_PROGRESS','IN_REVIEW','DONE');
CREATE TABLE "WorkspaceInvitation" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"email" TEXT NOT NULL,"role" "WorkspaceRole" NOT NULL DEFAULT 'MEMBER',"tokenHash" TEXT NOT NULL,"status" "InvitationStatus" NOT NULL DEFAULT 'PENDING',"inviterId" TEXT NOT NULL,"accepterId" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"acceptedAt" TIMESTAMP(3),CONSTRAINT "WorkspaceInvitation_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "WorkspaceInvitation_tokenHash_key" ON "WorkspaceInvitation"("tokenHash");
CREATE INDEX "WorkspaceInvitation_workspaceId_email_status_idx" ON "WorkspaceInvitation"("workspaceId","email","status");
CREATE INDEX "WorkspaceInvitation_email_status_idx" ON "WorkspaceInvitation"("email","status");
CREATE INDEX "WorkspaceInvitation_workspaceId_status_idx" ON "WorkspaceInvitation"("workspaceId","status");
CREATE TABLE "Project" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"status" "ProjectStatus" NOT NULL DEFAULT 'PLANNING',"priority" "ProjectPriority" NOT NULL DEFAULT 'MEDIUM',"startDate" TIMESTAMP(3),"dueDate" TIMESTAMP(3),"budget" DECIMAL(14,2),"currency" TEXT NOT NULL DEFAULT 'USD',"progress" INTEGER NOT NULL DEFAULT 0,"archivedAt" TIMESTAMP(3),"createdById" TEXT NOT NULL,"assigneeId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_pkey" PRIMARY KEY("id"));
CREATE INDEX "Project_workspaceId_status_idx" ON "Project"("workspaceId","status");
CREATE INDEX "Project_workspaceId_dueDate_idx" ON "Project"("workspaceId","dueDate");
